const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const taipei = ee.Geometry.Point([121.5654, 25.0330]);
    const day_of_year_start = 17;
    const day_of_year_end = 24;

    // Define the time periods
    const baseline_start_year = 2001;
    const baseline_end_year = 2010;
    const comparison_year = 2016;

    // 2. Data Acquisition
    const modisLST = ee.ImageCollection('MODIS/061/MOD11A1');

    // Function to scale and mask LST data
    function processLST(image) {
        // According to MODIS user guide, Mandatory QA flag bits 0-1 == 00 means good data
        const quality = image.select('QC_Day');
        const goodQuality = quality.bitwiseAnd(3).eq(0); // Bits 0-1 are for mandatory QA

        return image.select('LST_Day_1km')
            .multiply(0.02) // Apply scale factor to get Kelvin
            .subtract(273.15) // Convert Kelvin to Celsius
            .updateMask(goodQuality)
            .rename('LST_Celsius');
    }

    // Baseline Collection (2001-2010)
    const baselineCol = modisLST.filter(ee.Filter.calendarRange(baseline_start_year, baseline_end_year, 'year'))
        .filter(ee.Filter.calendarRange(day_of_year_start, day_of_year_end, 'day_of_year'))
        .map(processLST);

    // Comparison Collection (2016)
    const comparisonCol = modisLST.filter(ee.Filter.date(`${comparison_year}-01-17`, `${comparison_year}-01-25`))
        .map(processLST);

    // 3. Data Availability Check
    const baselineSize = baselineCol.size().getInfo();
    const comparisonSize = comparisonCol.size().getInfo();

    if (baselineSize === 0 || comparisonSize === 0) {
        console.log(`Baseline (2001-2010) images: ${baselineSize}`);
        console.log(`Comparison (2016) images: ${comparisonSize}`);
        console.log("Empty collection for one or both periods.");
        console.log("B"); // Answer is B since the question is about decrease, no data means it didn't decrease
        return;
    }
    console.log(`Baseline (2001-2010) image count: ${baselineSize}`);
    console.log(`Comparison (2016) image count: ${comparisonSize}`);

    // 4. Processing & Calculation
    const baselineMeanImage = baselineCol.mean();
    const comparisonMeanImage = comparisonCol.mean();

    const scale = 1000; // MODIS 1km resolution

    // Get baseline stats
    const baselineStats = baselineMeanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: taipei,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    // Get comparison stats
    const comparisonStats = comparisonMeanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: taipei,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const baselineLST = baselineStats['LST_Celsius_mean'];
    const baselinePixels = baselineStats['LST_Celsius_count'];
    const comparisonLST = comparisonStats['LST_Celsius_mean'];
    const comparisonPixels = comparisonStats['LST_Celsius_count'];

    // 5. Validation & Final Answer
    if (baselinePixels === 0 || comparisonPixels === 0) {
        console.log(`Baseline valid pixel count: ${baselinePixels}`);
        console.log(`Comparison valid pixel count: ${comparisonPixels}`);
        console.log("No valid pixels after cloud/quality masking.");
        console.log("C2");
        return;
    }
    console.log(`Baseline valid pixels: ${baselinePixels}`);
    console.log(`Comparison valid pixels: ${comparisonPixels}`);


    if (baselineLST === null || comparisonLST === null) {
        console.log("Calculation failed, resulted in null value.");
        console.log("C3");
        return;
    }

    console.log(`Avg LST 2001-2010 (Jan 17-24): ${baselineLST.toFixed(2)} C`);
    console.log(`Avg LST 2016 (Jan 17-24): ${comparisonLST.toFixed(2)} C`);

    if (comparisonLST < baselineLST) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error(`Initialization or analysis failed: ${e}`);
        console.log("D");
    }
}

initEE();
